-- enrich_20261007_greentown_partners_priority.sql
-- MBG priority for the 50 Greentown Labs Houston corporate partners:
--   two interest_tags per company (app.parties has no tier column):
--     MBG Tier 1 = contact first, MBG Tier 2 = evaluate, MBG Tier 3 = low
--     plus one MBG category tag. Previous MBG tags are replaced.
-- Data is base64 JSON. Idempotent.

with x as (
  select *
  from jsonb_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::jsonb)
       as t(id uuid, tier text, tag text)
)
update app.parties p
set interest_tags = coalesce(
      (select jsonb_agg(e)
         from jsonb_array_elements(case when jsonb_typeof(p.interest_tags) = 'array'
                                        then p.interest_tags else '[]'::jsonb end) e
        where coalesce(e #>> '{}', '') not like 'MBG %'),
      '[]'::jsonb) || jsonb_build_array(x.tier, x.tag),
    updated_at = now()
from x
where p.id = x.id
  and p.deleted_at is null
returning p.party_name, x.tier, x.tag, p.interest_tags;
